BEGIN;

INSERT INTO permission_catalog(permission_code,domain,risk_class,sod_class) VALUES
 ('REPORT.FORECAST.VIEW','REPORTING','LOW','READ'),
 ('REPORT.FORECAST.CREATE','REPORTING','HIGH','FORECAST_DRAFT'),
 ('REPORT.FORECAST.SUBMIT','REPORTING','HIGH','FORECAST_SUBMIT'),
 ('REPORT.FORECAST.APPROVE','REPORTING','CRITICAL','FORECAST_APPROVE')
ON CONFLICT(permission_code) DO UPDATE SET active=true,domain=EXCLUDED.domain,risk_class=EXCLUDED.risk_class,sod_class=EXCLUDED.sod_class,version=permission_catalog.version+1,effective_to=NULL;
INSERT INTO runtime_human_permission_authority(permission_code,authority_class) VALUES
 ('REPORT.FORECAST.VIEW','READ'),('REPORT.FORECAST.CREATE','DRAFT'),('REPORT.FORECAST.SUBMIT','SUBMIT'),('REPORT.FORECAST.APPROVE','APPROVE')
ON CONFLICT(permission_code) DO UPDATE SET authority_class=EXCLUDED.authority_class;

CREATE TABLE forecast_workflow(
 forecast_workflow_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenant(tenant_id),entity_id uuid NOT NULL,period_id uuid NOT NULL,
 name text NOT NULL CHECK(name=btrim(name) AND length(name) BETWEEN 1 AND 160),currency char(3) NOT NULL CHECK(currency~'^[A-Z]{3}$'),version bigint NOT NULL CHECK(version>0),
 snapshot_hash text NOT NULL CHECK(snapshot_hash~'^sha256:[0-9a-f]{64}$'),status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','PENDING_APPROVAL','APPROVED')),revision bigint NOT NULL DEFAULT 0 CHECK(revision>=0),
 created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),submitted_by text,submitted_at timestamptz,approved_by text,approved_at timestamptz,
 UNIQUE(tenant_id,entity_id,period_id,name,version),UNIQUE(tenant_id,forecast_workflow_id),FOREIGN KEY(tenant_id,entity_id,period_id) REFERENCES accounting_period(tenant_id,entity_id,period_id),
 CHECK((submitted_by IS NULL)=(submitted_at IS NULL) AND (approved_by IS NULL)=(approved_at IS NULL)),CHECK(submitted_by IS NULL OR submitted_by<>created_by),CHECK(approved_by IS NULL OR approved_by<>created_by AND approved_by<>submitted_by),
 CHECK((status='DRAFT' AND revision=0 AND submitted_by IS NULL AND approved_by IS NULL) OR(status='PENDING_APPROVAL' AND revision=1 AND submitted_by IS NOT NULL AND approved_by IS NULL) OR(status='APPROVED' AND revision=2 AND submitted_by IS NOT NULL AND approved_by IS NOT NULL))
);
CREATE TABLE forecast_line(forecast_workflow_id uuid NOT NULL,tenant_id uuid NOT NULL,entity_id uuid NOT NULL,period_id uuid NOT NULL,account_code text NOT NULL CHECK(account_code~'^[0-9A-Za-z._-]{1,64}$'),amount numeric(20,4) NOT NULL CHECK(amount>=0),budget_snapshot_id uuid NOT NULL,budget_version bigint NOT NULL CHECK(budget_version>0),budget_snapshot_hash text NOT NULL CHECK(budget_snapshot_hash~'^sha256:[0-9a-f]{64}$'),posted_actual_evidence_hash text NOT NULL CHECK(posted_actual_evidence_hash~'^sha256:[0-9a-f]{64}$'),line_hash text NOT NULL CHECK(line_hash~'^sha256:[0-9a-f]{64}$'),PRIMARY KEY(forecast_workflow_id,account_code),FOREIGN KEY(tenant_id,forecast_workflow_id) REFERENCES forecast_workflow(tenant_id,forecast_workflow_id),FOREIGN KEY(budget_snapshot_id,tenant_id,entity_id,period_id) REFERENCES budget_snapshot(budget_snapshot_id,tenant_id,entity_id,period_id));
CREATE TABLE forecast_workflow_history(forecast_workflow_history_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),forecast_workflow_id uuid NOT NULL,tenant_id uuid NOT NULL,from_status text,to_status text NOT NULL CHECK(to_status IN('DRAFT','PENDING_APPROVAL','APPROVED')),revision bigint NOT NULL CHECK(revision>=0),actor_id text NOT NULL,reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 8 AND 2000),event_hash text NOT NULL CHECK(event_hash~'^sha256:[0-9a-f]{64}$'),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(forecast_workflow_id,revision),FOREIGN KEY(tenant_id,forecast_workflow_id) REFERENCES forecast_workflow(tenant_id,forecast_workflow_id));
CREATE TABLE forecast_workflow_gate(backend_pid integer NOT NULL,transaction_id bigint NOT NULL,tenant_id uuid NOT NULL,forecast_workflow_id uuid NOT NULL,operation text NOT NULL CHECK(operation IN('PENDING_APPROVAL','APPROVED')),PRIMARY KEY(backend_pid,transaction_id,tenant_id,forecast_workflow_id,operation));
ALTER TABLE forecast_workflow ENABLE ROW LEVEL SECURITY;ALTER TABLE forecast_line ENABLE ROW LEVEL SECURITY;ALTER TABLE forecast_workflow_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY forecast_workflow_scope ON forecast_workflow USING(tenant_id=refs_current_tenant() AND refs_entity_allowed(entity_id));
CREATE POLICY forecast_line_scope ON forecast_line USING(tenant_id=refs_current_tenant() AND refs_entity_allowed(entity_id));
CREATE POLICY forecast_history_scope ON forecast_workflow_history USING(EXISTS(SELECT 1 FROM forecast_workflow w WHERE w.tenant_id=refs_current_tenant() AND w.forecast_workflow_id=forecast_workflow_history.forecast_workflow_id AND refs_entity_allowed(w.entity_id)));
REVOKE ALL ON forecast_workflow,forecast_line,forecast_workflow_history,forecast_workflow_gate FROM PUBLIC,refs_app;
CREATE FUNCTION refs_guard_forecast_workflow() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Forecast workflow is retained evidence' USING ERRCODE='55000';END IF;
 IF NOT EXISTS(SELECT 1 FROM forecast_workflow_gate g WHERE g.backend_pid=pg_backend_pid() AND g.transaction_id=txid_current() AND g.tenant_id=OLD.tenant_id AND g.forecast_workflow_id=OLD.forecast_workflow_id AND g.operation=NEW.status) OR NEW.revision<>OLD.revision+1 OR (to_jsonb(NEW)-ARRAY['status','revision','submitted_by','submitted_at','approved_by','approved_at']::text[]) IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','revision','submitted_by','submitted_at','approved_by','approved_at']::text[]) THEN RAISE EXCEPTION 'Forecast workflow mutation requires an authoritative command' USING ERRCODE='42501';END IF;RETURN NEW;
END;$$;
CREATE TRIGGER forecast_workflow_protect BEFORE UPDATE OR DELETE ON forecast_workflow FOR EACH ROW EXECUTE FUNCTION refs_guard_forecast_workflow();
CREATE TRIGGER forecast_line_append_only BEFORE UPDATE OR DELETE ON forecast_line FOR EACH ROW EXECUTE FUNCTION reject_mutation();CREATE TRIGGER forecast_history_append_only BEFORE UPDATE OR DELETE ON forecast_workflow_history FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE FUNCTION refs_forecast_create_hash(p_tenant uuid,p_entity uuid,p_period uuid,p_name text,p_currency text,p_lines jsonb,p_reason text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$ SELECT refs_jsonb_hash(jsonb_build_object('schema_version','FORECAST_CREATE_V1','tenant_id',p_tenant,'entity_id',p_entity,'period_id',p_period,'name',p_name,'currency',p_currency,'lines',p_lines,'reason',p_reason)) $$;
CREATE FUNCTION refs_forecast_transition_hash(p_tenant uuid,p_entity uuid,p_workflow uuid,p_action text,p_revision bigint,p_reason text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$ SELECT refs_jsonb_hash(jsonb_build_object('schema_version','FORECAST_TRANSITION_V1','tenant_id',p_tenant,'entity_id',p_entity,'workflow_id',p_workflow,'action',p_action,'revision',p_revision,'reason',p_reason)) $$;
CREATE FUNCTION refs_forecast_payload(p_tenant uuid,p_entity uuid,p_workflow uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ DECLARE w forecast_workflow;lines jsonb;history jsonb;actor text:=refs_current_actor();BEGIN
 PERFORM refs_assert_scope(p_tenant,p_entity,'REPORT.FORECAST.VIEW');SELECT * INTO w FROM forecast_workflow WHERE tenant_id=p_tenant AND entity_id=p_entity AND forecast_workflow_id=p_workflow;IF NOT FOUND THEN RAISE EXCEPTION 'Forecast workflow not found' USING ERRCODE='P0002';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('account_code',l.account_code,'amount',l.amount::text,'budget_snapshot_id',l.budget_snapshot_id,'budget_version',l.budget_version::text,'budget_snapshot_hash',l.budget_snapshot_hash,'posted_actual_evidence_hash',l.posted_actual_evidence_hash,'line_hash',l.line_hash) ORDER BY l.account_code),'[]'::jsonb) INTO lines FROM forecast_line l WHERE l.tenant_id=p_tenant AND l.forecast_workflow_id=p_workflow;
 SELECT coalesce(jsonb_agg(jsonb_build_object('from_status',h.from_status,'to_status',h.to_status,'revision',h.revision::text,'actor_id',h.actor_id,'reason',h.reason,'event_hash',h.event_hash,'created_at',h.created_at) ORDER BY h.revision),'[]'::jsonb) INTO history FROM forecast_workflow_history h WHERE h.tenant_id=p_tenant AND h.forecast_workflow_id=p_workflow;
 RETURN jsonb_build_object('schema_version','FORECAST_WORKFLOW_V1','forecast_workflow_id',w.forecast_workflow_id,'tenant_id',w.tenant_id,'entity_id',w.entity_id,'period_id',w.period_id,'name',w.name,'currency',w.currency,'version',w.version::text,'snapshot_hash',w.snapshot_hash,'status',w.status,'revision',w.revision::text,'lines',lines,'created_by',w.created_by,'created_at',w.created_at,'submitted_by',w.submitted_by,'submitted_at',w.submitted_at,'approved_by',w.approved_by,'approved_at',w.approved_at,'history',history,'action_flags',jsonb_build_object('can_create_draft',false,'can_submit',w.status='DRAFT' AND refs_entity_has_permission(p_entity,'REPORT.FORECAST.SUBMIT'),'can_review',false,'can_approve',w.status='PENDING_APPROVAL' AND actor IS DISTINCT FROM w.created_by AND actor IS DISTINCT FROM w.submitted_by AND refs_entity_has_permission(p_entity,'REPORT.FORECAST.APPROVE'),'can_post',false));
END;$$;
CREATE FUNCTION refs_create_forecast_workflow(p_tenant uuid,p_entity uuid,p_period uuid,p_name text,p_currency text,p_lines jsonb,p_reason text,p_idempotency_key text,p_request_hash text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ DECLARE actor text:=refs_current_actor();idem idempotency_receipt;workflow uuid:=gen_random_uuid();v bigint;line jsonb;payload jsonb;BEGIN
 IF actor IS NULL OR p_name IS NULL OR p_name<>btrim(p_name) OR length(p_name) NOT BETWEEN 1 AND 160 OR p_currency !~'^[A-Z]{3}$' OR jsonb_typeof(p_lines)<>'array' OR jsonb_array_length(p_lines) NOT BETWEEN 1 AND 1000 OR length(btrim(coalesce(p_reason,''))) NOT BETWEEN 8 AND 2000 OR length(coalesce(p_idempotency_key,'')) NOT BETWEEN 8 AND 200 OR p_request_hash IS DISTINCT FROM refs_forecast_create_hash(p_tenant,p_entity,p_period,p_name,p_currency,p_lines,p_reason) THEN RAISE EXCEPTION 'Invalid forecast create command' USING ERRCODE='22023';END IF;
 PERFORM refs_assert_scope(p_tenant,p_entity,'REPORT.FORECAST.CREATE');PERFORM refs_assert_scope(p_tenant,p_entity,'REPORT.FORECAST.VIEW');
 INSERT INTO idempotency_receipt(tenant_id,operation_scope,idempotency_key,request_hash,status,actor_id) VALUES(p_tenant,'FORECAST_CREATE:'||p_entity,p_idempotency_key,p_request_hash,'IN_PROGRESS',actor) ON CONFLICT DO NOTHING;SELECT * INTO idem FROM idempotency_receipt WHERE tenant_id=p_tenant AND operation_scope='FORECAST_CREATE:'||p_entity AND idempotency_key=p_idempotency_key FOR UPDATE;IF idem.actor_id IS DISTINCT FROM actor OR idem.request_hash IS DISTINCT FROM p_request_hash THEN RAISE EXCEPTION 'Forecast idempotency conflict' USING ERRCODE='23505';END IF;IF idem.status='SUCCEEDED' THEN RETURN idem.response_body||jsonb_build_object('idempotent',true);END IF;
 IF NOT EXISTS(SELECT 1 FROM accounting_period p JOIN entity e ON e.tenant_id=p.tenant_id AND e.entity_id=p.entity_id WHERE p.tenant_id=p_tenant AND p.entity_id=p_entity AND p.period_id=p_period AND p.ledger_code='PRIMARY' AND p.status='OPEN' AND e.base_currency=p_currency FOR SHARE) THEN RAISE EXCEPTION 'Forecast requires an OPEN primary period and entity currency' USING ERRCODE='23514';END IF;
 FOR line IN SELECT value FROM jsonb_array_elements(p_lines) LOOP IF ARRAY(SELECT jsonb_object_keys(line) ORDER BY 1)<>ARRAY['account_code','amount','budget_snapshot_hash','budget_snapshot_id','budget_version','line_hash','posted_actual_evidence_hash'] OR line->>'account_code'!~'^[0-9A-Za-z._-]{1,64}$' OR line->>'amount'!~'^(0|[1-9][0-9]{0,15})\\.[0-9]{4}$' OR line->>'budget_snapshot_id'!~'^[0-9a-f-]{36}$' OR line->>'budget_version'!~'^[1-9][0-9]*$' OR line->>'budget_snapshot_hash'!~'^sha256:[0-9a-f]{64}$' OR line->>'posted_actual_evidence_hash'!~'^sha256:[0-9a-f]{64}$' OR line->>'line_hash'!~'^sha256:[0-9a-f]{64}$' OR (line->>'line_hash') IS DISTINCT FROM refs_jsonb_hash(jsonb_build_object('account_code',line->>'account_code','amount',line->>'amount','budget_snapshot_id',line->>'budget_snapshot_id','budget_version',line->>'budget_version','budget_snapshot_hash',line->>'budget_snapshot_hash','posted_actual_evidence_hash',line->>'posted_actual_evidence_hash')) OR NOT EXISTS(SELECT 1 FROM account_master a WHERE a.tenant_id=p_tenant AND a.entity_id=p_entity AND a.account_code=line->>'account_code' AND a.active FOR SHARE) OR NOT EXISTS(SELECT 1 FROM budget_snapshot bs WHERE bs.tenant_id=p_tenant AND bs.entity_id=p_entity AND bs.period_id=p_period AND bs.budget_snapshot_id=(line->>'budget_snapshot_id')::uuid AND bs.version=(line->>'budget_version')::bigint AND bs.snapshot_hash=line->>'budget_snapshot_hash' AND bs.approved_by IS NOT NULL FOR SHARE) OR NOT EXISTS(SELECT 1 FROM ledger_line ll JOIN journal_entry j ON j.tenant_id=ll.tenant_id AND j.entity_id=ll.entity_id AND j.journal_entry_id=ll.journal_entry_id AND j.status='POSTED' WHERE ll.tenant_id=p_tenant AND ll.entity_id=p_entity AND ll.period_id=p_period AND ll.account_code=line->>'account_code' HAVING refs_jsonb_hash(jsonb_build_object('account_code',line->>'account_code','ledger_line_ids',to_jsonb(array_agg(ll.ledger_line_id ORDER BY ll.ledger_line_id))))=line->>'posted_actual_evidence_hash') THEN RAISE EXCEPTION 'Forecast lines must bind approved budget and posted actual evidence' USING ERRCODE='23514';END IF;END LOOP;
 IF (SELECT count(DISTINCT value->>'account_code') FROM jsonb_array_elements(p_lines))<>jsonb_array_length(p_lines) THEN RAISE EXCEPTION 'Forecast lines duplicate an account' USING ERRCODE='23514';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('FORECAST:'||p_entity::text||':'||p_period::text||':'||p_name,0));SELECT coalesce(max(version),0)+1 INTO v FROM forecast_workflow WHERE tenant_id=p_tenant AND entity_id=p_entity AND period_id=p_period AND name=p_name;
 INSERT INTO forecast_workflow(forecast_workflow_id,tenant_id,entity_id,period_id,name,currency,version,snapshot_hash,created_by) VALUES(workflow,p_tenant,p_entity,p_period,p_name,p_currency,v,refs_jsonb_hash(jsonb_build_object('name',p_name,'currency',p_currency,'lines',p_lines)),actor);
 INSERT INTO forecast_line(forecast_workflow_id,tenant_id,entity_id,period_id,account_code,amount,budget_snapshot_id,budget_version,budget_snapshot_hash,posted_actual_evidence_hash,line_hash) SELECT workflow,p_tenant,p_entity,p_period,value->>'account_code',(value->>'amount')::numeric,(value->>'budget_snapshot_id')::uuid,(value->>'budget_version')::bigint,value->>'budget_snapshot_hash',value->>'posted_actual_evidence_hash',value->>'line_hash' FROM jsonb_array_elements(p_lines);
 payload:=refs_forecast_payload(p_tenant,p_entity,workflow)||jsonb_build_object('idempotent',false);INSERT INTO forecast_workflow_history(forecast_workflow_id,tenant_id,from_status,to_status,revision,actor_id,reason,event_hash) VALUES(workflow,p_tenant,NULL,'DRAFT',0,actor,btrim(p_reason),refs_jsonb_hash(payload));INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,p_entity,'FORECAST_DRAFT_CREATED','FORECAST_WORKFLOW',workflow,'CREATE',actor,'USER','REPORT.FORECAST.CREATE',p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),btrim(p_reason),payload);INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_entity,'FORECAST_WORKFLOW',workflow,'FORECAST_DRAFT_CREATED',payload,refs_jsonb_hash(payload));UPDATE idempotency_receipt SET status='SUCCEEDED',response_status=201,response_body=payload,completed_at=clock_timestamp() WHERE idempotency_receipt_id=idem.idempotency_receipt_id;RETURN payload;
END;$$;
CREATE FUNCTION refs_transition_forecast_workflow(p_tenant uuid,p_entity uuid,p_workflow uuid,p_action text,p_revision bigint,p_reason text,p_idempotency_key text,p_request_hash text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ DECLARE actor text:=refs_current_actor();action text:=upper(p_action);idem idempotency_receipt;w forecast_workflow;next_status text;payload jsonb;BEGIN
 IF actor IS NULL OR action NOT IN('SUBMIT','APPROVE') OR p_revision IS NULL OR p_revision<0 OR length(btrim(coalesce(p_reason,''))) NOT BETWEEN 8 AND 2000 OR length(coalesce(p_idempotency_key,'')) NOT BETWEEN 8 AND 200 OR p_request_hash IS DISTINCT FROM refs_forecast_transition_hash(p_tenant,p_entity,p_workflow,action,p_revision,p_reason) THEN RAISE EXCEPTION 'Invalid forecast transition' USING ERRCODE='22023';END IF;PERFORM refs_assert_scope(p_tenant,p_entity,'REPORT.FORECAST.'||action);PERFORM refs_assert_scope(p_tenant,p_entity,'REPORT.FORECAST.VIEW');INSERT INTO idempotency_receipt(tenant_id,operation_scope,idempotency_key,request_hash,status,actor_id) VALUES(p_tenant,'FORECAST_'||action||':'||p_entity,p_idempotency_key,p_request_hash,'IN_PROGRESS',actor) ON CONFLICT DO NOTHING;SELECT * INTO idem FROM idempotency_receipt WHERE tenant_id=p_tenant AND operation_scope='FORECAST_'||action||':'||p_entity AND idempotency_key=p_idempotency_key FOR UPDATE;IF idem.actor_id IS DISTINCT FROM actor OR idem.request_hash IS DISTINCT FROM p_request_hash THEN RAISE EXCEPTION 'Forecast idempotency conflict' USING ERRCODE='23505';END IF;IF idem.status='SUCCEEDED' THEN RETURN idem.response_body||jsonb_build_object('idempotent',true);END IF;
 SELECT * INTO w FROM forecast_workflow WHERE tenant_id=p_tenant AND entity_id=p_entity AND forecast_workflow_id=p_workflow FOR UPDATE;IF NOT FOUND OR w.revision<>p_revision OR(action='SUBMIT' AND w.status<>'DRAFT')OR(action='APPROVE' AND(w.status<>'PENDING_APPROVAL' OR actor IN(w.created_by,w.submitted_by))) OR NOT EXISTS(SELECT 1 FROM accounting_period WHERE tenant_id=p_tenant AND entity_id=p_entity AND period_id=w.period_id AND ledger_code='PRIMARY' AND status='OPEN' FOR SHARE) OR EXISTS(SELECT 1 FROM forecast_line f LEFT JOIN budget_snapshot bs ON bs.tenant_id=f.tenant_id AND bs.entity_id=f.entity_id AND bs.period_id=f.period_id AND bs.budget_snapshot_id=f.budget_snapshot_id AND bs.version=f.budget_version AND bs.snapshot_hash=f.budget_snapshot_hash AND bs.approved_by IS NOT NULL WHERE f.tenant_id=p_tenant AND f.forecast_workflow_id=p_workflow AND(bs.budget_snapshot_id IS NULL OR NOT EXISTS(SELECT 1 FROM ledger_line ll JOIN journal_entry j ON j.tenant_id=ll.tenant_id AND j.entity_id=ll.entity_id AND j.journal_entry_id=ll.journal_entry_id AND j.status='POSTED' WHERE ll.tenant_id=f.tenant_id AND ll.entity_id=f.entity_id AND ll.period_id=f.period_id AND ll.account_code=f.account_code HAVING refs_jsonb_hash(jsonb_build_object('account_code',f.account_code,'ledger_line_ids',to_jsonb(array_agg(ll.ledger_line_id ORDER BY ll.ledger_line_id))))=f.posted_actual_evidence_hash))) THEN RAISE EXCEPTION 'Forecast revision, evidence, period, or separation of duties conflict' USING ERRCODE='40001';END IF;next_status:=CASE action WHEN 'SUBMIT' THEN 'PENDING_APPROVAL' ELSE 'APPROVED' END;INSERT INTO forecast_workflow_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_workflow,next_status);UPDATE forecast_workflow SET status=next_status,revision=revision+1,submitted_by=CASE WHEN action='SUBMIT' THEN actor ELSE submitted_by END,submitted_at=CASE WHEN action='SUBMIT' THEN clock_timestamp() ELSE submitted_at END,approved_by=CASE WHEN action='APPROVE' THEN actor ELSE approved_by END,approved_at=CASE WHEN action='APPROVE' THEN clock_timestamp() ELSE approved_at END WHERE tenant_id=p_tenant AND forecast_workflow_id=p_workflow;DELETE FROM forecast_workflow_gate WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current() AND tenant_id=p_tenant AND forecast_workflow_id=p_workflow AND operation=next_status;payload:=refs_forecast_payload(p_tenant,p_entity,p_workflow)||jsonb_build_object('idempotent',false);INSERT INTO forecast_workflow_history(forecast_workflow_id,tenant_id,from_status,to_status,revision,actor_id,reason,event_hash) VALUES(p_workflow,p_tenant,w.status,next_status,w.revision+1,actor,btrim(p_reason),refs_jsonb_hash(payload));INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,p_entity,'FORECAST_'||action,'FORECAST_WORKFLOW',p_workflow,action,actor,'USER','REPORT.FORECAST.'||action,p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),btrim(p_reason),payload);INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_entity,'FORECAST_WORKFLOW',p_workflow,'FORECAST_'||action,payload,refs_jsonb_hash(payload));UPDATE idempotency_receipt SET status='SUCCEEDED',response_status=200,response_body=payload,completed_at=clock_timestamp() WHERE idempotency_receipt_id=idem.idempotency_receipt_id;RETURN payload;
END;$$;
CREATE FUNCTION refs_read_forecast_workflow(p_tenant uuid,p_entity uuid,p_workflow uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ SELECT refs_forecast_payload(p_tenant,p_entity,p_workflow) $$;
REVOKE ALL ON FUNCTION refs_forecast_create_hash(uuid,uuid,uuid,text,text,jsonb,text),refs_forecast_transition_hash(uuid,uuid,uuid,text,bigint,text),refs_forecast_payload(uuid,uuid,uuid),refs_create_forecast_workflow(uuid,uuid,uuid,text,text,jsonb,text,text,text),refs_transition_forecast_workflow(uuid,uuid,uuid,text,bigint,text,text,text),refs_read_forecast_workflow(uuid,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION refs_forecast_create_hash(uuid,uuid,uuid,text,text,jsonb,text),refs_forecast_transition_hash(uuid,uuid,uuid,text,bigint,text),refs_create_forecast_workflow(uuid,uuid,uuid,text,text,jsonb,text,text,text),refs_transition_forecast_workflow(uuid,uuid,uuid,text,bigint,text,text,text),refs_read_forecast_workflow(uuid,uuid,uuid) TO refs_app;
COMMIT;
